/// Light or dark appearance.
enum MistyAppearance { light, dark }

/// The translucent grades of glass. Cloud is solid: use the cloud colour.
enum MistyGlassGrade { clear, mist, veil }

/// An OKLCH colour. When [followsHue] is true, [h] is an offset from the Misty hue.
class MistyOklch {
  const MistyOklch(this.l, this.c, this.h, this.alpha, this.followsHue);

  final double l;
  final double c;
  final double h;
  final double alpha;
  final bool followsHue;

  /// sRGB, clipped per channel as browsers do on sRGB displays.
  Color resolve(double hue) {
    final angle = (followsHue ? hue + h : h) * math.pi / 180;
    final a = c * math.cos(angle);
    final b = c * math.sin(angle);
    final l3 = math.pow(l + 0.3963377774 * a + 0.2158037573 * b, 3).toDouble();
    final m3 = math.pow(l - 0.1055613458 * a - 0.0638541728 * b, 3).toDouble();
    final s3 = math.pow(l - 0.0894841775 * a - 1.2914855480 * b, 3).toDouble();
    int encode(double v) {
      final double g = v <= 0.0031308 ? 12.92 * v : 1.055 * math.pow(v, 1 / 2.4).toDouble() - 0.055;
      return (g.clamp(0.0, 1.0) * 255).round();
    }

    return Color.fromARGB(
      (alpha * 255).round(),
      encode(4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3),
      encode(-1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3),
      encode(-0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3),
    );
  }
}

