/// Glass: a tint of the field at a grade's alpha, over a blur of what lies behind.
class MistyGlass {
  MistyGlass._();

  static const lightness = 0.995;
  static const lightnessDark = 0.215;
  static const chroma = 0.004;
  static const chromaDark = 0.02;
  static const saturation = 1.75;

  static double alpha(MistyGlassGrade grade, MistyAppearance appearance) {
    final dark = appearance == MistyAppearance.dark;
    switch (grade) {
      case MistyGlassGrade.clear:
        return dark ? 0.36 : 0.3;
      case MistyGlassGrade.mist:
        return dark ? 0.5 : 0.42;
      case MistyGlassGrade.veil:
        return dark ? 0.68 : 0.62;
    }
  }

  /// The blur's standard deviation, for ImageFilter.blur.
  static double blur(MistyGlassGrade grade) {
    switch (grade) {
      case MistyGlassGrade.clear:
        return 24.0;
      case MistyGlassGrade.mist:
        return 26.0;
      case MistyGlassGrade.veil:
        return 32.0;
    }
  }
}

