/// Fluid type sizes from the window's width in logical pixels. Flutter then scales
/// them with the person's text size setting (PLT-06).
class MistyType {
  MistyType._();

  static double display(double windowWidth) => (windowWidth * 0.066).clamp(52.0, 92.0).toDouble();
  static double h1(double windowWidth) => (windowWidth * 0.046).clamp(38.4, 60.0).toDouble();
  static double h2(double windowWidth) => (windowWidth * 0.034).clamp(30.4, 44.0).toDouble();
  static double h3(double windowWidth) => (windowWidth * 0.02).clamp(20.8, 24.0).toDouble();
  static double lede(double windowWidth) => (windowWidth * 0.015).clamp(17.0, 19.0).toDouble();

  /// The longest line of running text, in characters.
  static const measure = 68;
}

