/// The five window classes, measured on the window's width.
enum MistyWindowClass {
  narrow, compact, medium, expanded, wide;

  static MistyWindowClass of(double width) {
    if (width <= 380) return MistyWindowClass.narrow;
    if (width <= 767) return MistyWindowClass.compact;
    if (width <= 1023) return MistyWindowClass.medium;
    if (width <= 1179) return MistyWindowClass.expanded;
    return MistyWindowClass.wide;
  }
}

